function dateText(value){try{return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(value))}catch{return 'Data indisponível'}}
function projectsPage(){return`${intro('Suas ideias, guardadas.','Crie, salve e volte quando quiser.','Meus projetos',`<div class="project-actions">${button('Importar','import','secondary','upload')}${button('Novo projeto','new-free','primary','plus')}</div>`).replace('class="intro"','class="intro project-intro"')}${projects.length?`<div class="project-grid">${projects.slice().sort((a,b)=>b.updated-a.updated).map(p=>`<article class="project-card"><button class="project-art" data-action="open-project" data-id="${escapeHTML(p.id)}" aria-label="Abrir ${escapeHTML(p.name)}"><span class="badge">Demonstração local</span>${sceneSVG(p.blocks)}</button><div class="project-info"><h2>${escapeHTML(p.name)}</h2><p>${p.blocks.length} blocos · ${dateText(p.updated)}</p><div class="project-footer"><button class="btn primary" data-action="open-project" data-id="${escapeHTML(p.id)}">Continuar ${icon('arrow')}</button><button class="icon-btn" data-action="rename" data-id="${escapeHTML(p.id)}" aria-label="Renomear ${escapeHTML(p.name)}">${icon('edit')}</button><button class="icon-btn" data-action="export" data-id="${escapeHTML(p.id)}" aria-label="Exportar ${escapeHTML(p.name)}">${icon('download')}</button><button class="icon-btn" data-action="delete" data-id="${escapeHTML(p.id)}" aria-label="Excluir ${escapeHTML(p.name)}">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<section class="project-empty"><div class="empty-icon">${icon('folder')}</div><h2>Abra espaço para uma ideia.</h2><p>Suas construções salvas ficam aqui, prontas para continuar.</p>${button('Criar meu primeiro projeto','new-free','primary','plus')}</section>`}<div class="storage-note">${icon('shield')}Armazenamento de demonstração: os projetos ficam somente neste navegador. Exporte um JSON para guardar uma cópia.</div>`}
function storageStatus(){try{const key='tvTouchPrototype.storageCheck';localStorage.setItem(key,'1');localStorage.removeItem(key);return'Disponível neste navegador'}catch{return'Indisponível neste navegador'}}
function settingsPage(){return`${intro('Do seu jeito.','Ajustes simples para criar com conforto.','Preferências e diagnóstico')}<div class="settings-grid"><section class="settings-card"><h2>${icon('settings')}Sua experiência</h2><div class="setting-row"><div class="setting-label"><strong>Perfil de interface</strong><span>A organização se adapta à tela. TV amplia os controles.</span></div><select id="profileSetting" aria-label="Perfil de interface"><option value="auto" ${settings.profile==='auto'?'selected':''}>Automático</option><option value="phone" ${settings.profile==='phone'?'selected':''}>Celular</option><option value="tv" ${settings.profile==='tv'?'selected':''}>TV</option></select></div><div class="setting-row"><div class="setting-label"><strong>Reduzir movimento</strong><span>Transições mais discretas, mantendo o controle das peças.</span></div><button class="switch ${settings.reduced?'on':''}" role="switch" aria-checked="${settings.reduced}" aria-label="Reduzir movimento" data-action="reduced"><span></span></button></div><div class="setting-row"><div class="setting-label"><strong>Meta de renderização</strong><span>Preferência para o app. Uma meta não comprova FPS real.</span></div><select id="fpsSetting" aria-label="Meta de renderização"><option value="30" ${settings.fps==='30'?'selected':''}>30 quadros/s</option><option value="60" ${settings.fps==='60'?'selected':''}>60 quadros/s</option></select></div></section><section class="settings-card"><h2>${icon('monitor')}Sobre este ambiente</h2><dl style="margin:0"><div class="diag-row"><dt>Execução</dt><dd>Protótipo no navegador</dd></div><div class="diag-row"><dt>Área disponível</dt><dd>${innerWidth} × ${innerHeight} px</dd></div><div class="diag-row"><dt>Pontos de toque informados</dt><dd>${navigator.maxTouchPoints||0} · informação do navegador</dd></div><div class="diag-row"><dt>Armazenamento</dt><dd>${storageStatus()}</dd></div><div class="diag-row"><dt>Câmera / realidade aumentada</dt><dd>Não implementadas nesta prévia</dd></div><div class="diag-row"><dt>FPS e desempenho físico</dt><dd>Não medidos</dd></div><div class="diag-row"><dt>Aceite da Samsung WA86F</dt><dd>Depende de teste na TV</dd></div></dl><div class="diag-note">Capacidade informada não é teste físico. Este diagnóstico não certifica o telefone ou a tela da escola.</div></section><section class="settings-card settings-wide"><p><strong>TV Touch · Criar. Experimentar. Aprender.</strong><br>Uma prévia do MVP: construção 3D, quatro missões e projetos locais. Câmera, realidade aumentada e movimento corporal pertencem à próxima etapa.</p>${button('Sobre esta prévia','about','secondary','info')}</section></div>`}
function resultPage(){const m=MISSIONS[state.builderMission]||MISSIONS.bridge,p=progress();return`<div class="back-row"><button class="icon-btn" data-action="return-builder" aria-label="Voltar à construção">${icon('back')}</button><div><div class="eyebrow">Missão concluída</div><span style="font-size:13px">${m.name}</span></div></div><section class="result-card"><div class="result-top"><div class="success-mark">${icon('check')}</div><div class="eyebrow">Você construiu uma possibilidade.</div><h1>${m.success}</h1><p>Seu objetivo está completo. A criação pode continuar.</p><div class="result-art">${sceneSVG(state.blocks)}</div></div><div class="result-bottom"><div class="result-stat"><strong>${p.done}/${p.total}</strong>posições do desafio preenchidas ${icon('check')}</div><div class="result-actions">${button('Salvar construção','save','primary','save')}${button('Continuar criando','return-builder','secondary','cube')}${button('Outra missão','other-mission','secondary','arrow')}</div><p class="result-note">Resultado calculado a partir dos blocos desta construção.</p></div></section>`}
const pageFunctions={home:homePage,explore:explorePage,mission:missionPage,builder:builderPage,projects:projectsPage,settings:settingsPage,result:resultPage};
function render(){if(rendererCleanup){rendererCleanup();rendererCleanup=null}$('#content').className='content'+(state.page==='builder'?' workspace-content':'');$('#content').innerHTML=(pageFunctions[state.page]||homePage)();$('.main-nav').innerHTML=navHTML(false);$('.bottom-nav').innerHTML=navHTML(true);$('#topLabel').textContent=state.page==='builder'?'ATELIÊ DE CONSTRUÇÃO':state.page==='projects'?'SUAS IDEIAS EM CONTINUIDADE':'LABORATÓRIO CRIATIVO';document.body.classList.toggle('app-builder',state.page==='builder');fillIcons();if(state.page==='builder'){setupRenderer();updateBuilderUI()}applySettings()}
function go(page,{force=false}={}){if(!force&&['builder','result'].includes(state.page)&&state.dirty&&page!=='builder'&&page!=='result'){askLeave(()=>go(page,{force:true}));return}state.page=page;render();window.scrollTo({top:0,behavior:'instant'})}
function startBuilder(mission=null,project=null){const run=()=>{state.builderMission=mission;state.blocks=project?project.blocks.map(b=>({...b})):[];state.history=[];state.redo=[];state.target=null;state.selected=null;state.dirty=false;state.projectId=project?.id||null;state.projectName=project?.name||(mission?MISSIONS[mission].name:'Nova construção');state.material='grass';state.tool='select';state.yaw=.72;state.zoom=1;go('builder',{force:true})};if(['builder','result'].includes(state.page)&&state.dirty)askLeave(run);else run()}
function snapshot(){return state.blocks.map(b=>({...b}))}
function remember(){state.history.push(snapshot());if(state.history.length>40)state.history.shift();state.redo=[]}
function edited(){state.dirty=true;updateBuilderUI();drawWorld()}
function updateBuilderUI(){if(state.page!=='builder')return;const p=progress(),validTarget=canPlace(state.target),canErase=state.selected&&has(state.selected.x,state.selected.y,state.selected.z);$('#blockCount').textContent=state.blocks.length+' blocos';$('#undoBtn').disabled=!state.history.length;$('#redoBtn').disabled=!state.redo.length;$('#placeBtn').disabled=state.tool==='rotate'||(state.tool==='erase'?!canErase:!validTarget);$('#placeBtn').innerHTML=icon(state.tool==='erase'?'erase':'plus')+(state.tool==='erase'?'Apagar bloco':'Colocar bloco');$('#selectionLabel').textContent=state.tool==='rotate'?'Explore outro ângulo':state.tool==='erase'?(canErase?'Peça selecionada':'Escolha uma peça'):(state.target?'Prévia selecionada':'Escolha uma posição');$('#selectionHelp').textContent=state.tool==='rotate'?'Arraste o palco ou use o botão de giro.':state.tool==='erase'?'Confirme para remover a peça.':(state.target?(validTarget?'Material: '+byMaterial(state.material).name+'. Confirme para colocar.':'Esta posição não recebe um bloco. Escolha outra.'):'Selecione um espaço no palco.');document.querySelectorAll('.tool[data-id]').forEach(b=>{b.classList.toggle('active',b.dataset.id===state.tool);b.setAttribute('aria-pressed',b.dataset.id===state.tool)});document.querySelectorAll('.material').forEach(b=>{b.classList.toggle('active',b.dataset.id===state.material);b.setAttribute('aria-pressed',b.dataset.id===state.material)});if(state.builderMission){$('#progressCount').textContent=p.done+'/'+p.total;$('#progressBar').style.width=(p.done/p.total*100)+'%';$('#missionResultBtn').disabled=!p.complete;$('#missionResultBtn').innerHTML=(p.complete?'Ver resultado':'Em construção')+' '+icon(p.complete?'arrow':'cube')}}
function place(){if(state.tool==='erase'){if(!state.selected||!has(state.selected.x,state.selected.y,state.selected.z))return;remember();state.blocks=state.blocks.filter(b=>posKey(b.x,b.y,b.z)!==posKey(state.selected.x,state.selected.y,state.selected.z));state.selected=null;state.target=null;edited();toast('Bloco removido. Você pode desfazer.');return}if(!canPlace(state.target))return;remember();state.blocks.push({...state.target,material:state.material});state.selected={...state.target};state.target=valid(state.target.x,state.target.y+1,state.target.z)?{...state.target,y:state.target.y+1}:null;edited();if(progress().complete)toast('Objetivo completo! Você já pode ver seu resultado.')}
function undo(){if(!state.history.length)return;state.redo.push(snapshot());state.blocks=state.history.pop();edited()}
function redo(){if(!state.redo.length)return;state.history.push(snapshot());state.blocks=state.redo.pop();edited()}
function openModal(title,body,buttons){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modalTitle">${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-buttons">${buttons}</div>`;if(!$('#modal').open)$('#modal').showModal();requestAnimationFrame(()=>{const input=$('#modal input');if(input){input.focus();input.select()}})}
function closeModal(){$('#modal').close()}
function askLeave(callback){state.pendingNav=callback;openModal('Guardar esta ideia?','<p>Sua construção tem alterações. Salve um projeto para continuar depois.</p>',button('Salvar','leave-save','primary','save')+button('Descartar','leave-discard','secondary',null)+button('Continuar aqui','modal-close','secondary',null))}
function saveDialog(after=null){state.afterSave=after;openModal('Dê um nome à sua criação.','<p>O projeto ficará neste navegador de demonstração. Você pode exportar uma cópia em JSON.</p><label for="projectNameInput">Nome do projeto</label><input id="projectNameInput" maxlength="60" value="'+escapeHTML(state.projectName==='Nova construção'?'':state.projectName)+'" placeholder="Ex.: Minha primeira ponte"><div class="modal-error" id="nameError" role="alert"></div>',button('Salvar projeto','save-confirm','primary','save')+button('Cancelar','modal-close','secondary',null))}
function persistProjects(next){try{localStorage.setItem(KEYS.projects,JSON.stringify(next));projects=next;return true}catch{toast('Não foi possível salvar. O armazenamento deste navegador está indisponível.');return false}}
function confirmSave(){const input=$('#projectNameInput'),name=input.value.trim();if(!name){$('#nameError').textContent='Escreva um nome para guardar seu projeto.';input.focus();return}const now=Date.now(),id=state.projectId||'project-'+now.toString(36)+'-'+Math.random().toString(36).slice(2,6),entry={id,name,updated:now,blocks:snapshot()};if(!persistProjects(projects.filter(p=>p.id!==id).concat([entry])))return;state.projectId=id;state.projectName=name;state.dirty=false;closeModal();if(state.page==='builder')$('#projectTitle').textContent=name;const callback=state.afterSave;state.afterSave=null;toast('Projeto salvo neste navegador de demonstração.');if(callback)callback()}
function validateWorld(data){if(!data||data.version!==1||!Array.isArray(data.blocks)||data.blocks.length>256)throw Error('O arquivo não tem o formato de projeto esperado.');const keys=new Set();return data.blocks.map(b=>{if(!b||!valid(b.x,b.y,b.z)||!MATERIALS.some(m=>m.id===b.material))throw Error('Há blocos ou materiais inválidos neste arquivo.');const k=posKey(b.x,b.y,b.z);if(keys.has(k))throw Error('O arquivo contém blocos repetidos na mesma posição.');keys.add(k);return{x:b.x,y:b.y,z:b.z,material:b.material}})}
function exportProject(id){const p=projects.find(x=>x.id===id);if(!p)return;const blob=new Blob([JSON.stringify({version:1,blocks:p.blocks},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(p.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,55)||'projeto')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Cópia JSON preparada para download.')}
function renameDialog(id){const p=projects.find(x=>x.id===id);if(!p)return;state.renameId=id;openModal('Um novo nome, a mesma ideia.','<label for="renameInput">Nome do projeto</label><input id="renameInput" maxlength="60" value="'+escapeHTML(p.name)+'"><div class="modal-error" id="nameError" role="alert"></div>',button('Renomear','rename-confirm','primary','check')+button('Cancelar','modal-close','secondary',null))}
function cameraInfo(){openModal('Além do toque, na próxima etapa.','<p>O plano inclui colocar construções no ambiente e participar de jogos com o corpo.</p><div class="modal-facts"><div class="modal-fact"><span>Realidade aumentada</span><b>Em desenvolvimento</b></div><div class="modal-fact"><span>Interação por câmera</span><b>Em desenvolvimento</b></div><div class="modal-fact"><span>Câmera nesta prévia</span><b>Não utilizada</b></div></div><p>Esta página não ativa a câmera nem simula rastreamento. O aplicativo precisará verificar recursos e desempenho em cada aparelho.</p>',button('Voltar a explorar','modal-close','primary','arrow'))}
